import {config} from './config.js';
import {getRound} from './rounds.js';
export const demoAddress='0xa7e4000000000000000000000000000000008f2c';
const delay=()=>new Promise(r=>setTimeout(r,350));
export class DemoWalletProvider{async connect(mode){await delay();if(mode==='connection-error')throw Error('Wallet connection failed. Try another demo scenario.');return demoAddress;}}
export class DemoBalanceProvider{async check(address,mode){await delay();if(!address)throw Error('Connect a wallet first.');if(mode==='verification-error')throw Error('Verification failed. Retry the check.');if(mode==='network')throw Error('Unsupported network. Switch the demo network.');return(mode==='insufficient'?7250000n:12500000n)*10n**18n;}}
export class DemoRegistrationProvider{constructor(){this.entries=new Map();}has(a,id){return this.entries.has(a+':'+id);}clear(){this.entries.clear();}async register({address,id,now,anchor,balance}){await delay();const round=getRound(now(),anchor);if(!address)throw Error('Connect a wallet first.');if(!round.entryOpen||id!==round.nextId)throw Error('Registration closed for this round.');if(balance<config.required*10n**18n)throw Error('Confirm eligibility first.');if(this.has(address,id))throw Error('Already registered for this round.');this.entries.set(address+':'+id,{address,id});return{id};}}
export class DemoResultsProvider{async leaderboard(mode){await delay();if(mode==='leaderboard-error')throw Error('Leaderboard unavailable');if(mode==='empty')return[];const values=[142.86,118.42,104.2,97.35,89.72,82.14,76.9,68.53,61.24,55.81,53.44,51.2,50,47.32,41.08,35.1,29.77,24.02,17.3,9.82,4.32,-2.13,-9.52,-17.7];return values.map((v,i)=>{const start=BigInt(100+i*13)*10n**16n,ret=BigInt(Math.round(v*1e6));return{address:({below:15,top:3,outside:11,exact:12}[mode]===i)?demoAddress:'0x'+(40960+i*271).toString(16).padStart(4,'0')+'0'.repeat(32)+(4816+i*117).toString(16).padStart(4,'0'),start,current:start*(100000000n+ret)/100000000n,ret};});}}
export class DemoPayoutProvider{history(anchor){return[41,40,39].map((id,i)=>({id,start:anchor-(i+1)*config.roundMs,end:anchor-i*config.roundMs,participants:24+i*7,pool:BigInt(112+i*16)*10n**17n,status:'Finalized',payment:'Not paid',transactionHash:null,winners:Array.from({length:10},(_,j)=>({address:'0x'+(45800+j*127).toString(16)+'…'+(63500+j*12).toString(16),ret:132.75-j*7.21}))}));}}
